import java.util.*;
import java.io.*;

public class Main {
    static final int[][] directions = {{-1,0},{1,0},{0,-1},{0,1}};
    static int S, T, tot=1, n, tt, inf, b[], q[], a[][], dep[][], dis[][], p[][], s[][];
    static char ma[][], mb[][];
    static final int MAX_N = 20;
    static final int MAX_T = 1000;
    static final int MAX_Q = 1000000;
    static final int MAX_A = 3;
    static int[] d = new int[1000];

    static List<Integer>[] adj;
    static int[] head;

    static void addEdge(int x, int y, int c) {
        a[++tot][0] = y; a[tot][1] = c; a[tot][2] = b[x]; b[x] = tot;
        a[++tot][0] = x; a[tot][1] = 0; a[tot][2] = b[y]; b[y] = tot;
    }

    static void bfs(int x0, int y0, boolean flag) {
        int l=1, r=1, id=p[x0][y0];
        q[l] = x0*1000 + y0;
        for (int[] row : dis) Arrays.fill(row, Integer.MAX_VALUE);
        inf = Integer.MAX_VALUE;
        dis[x0][y0] = 0;
        while (l <= r) {
            int x = q[l]/1000, y = q[l]%1000; l++;
            if (flag && s[x][y]!=0 && dis[x][y]<=tt && dis[x][y]<=dep[x][y])
                addEdge(id, s[x][y], inf);
            if (dis[x][y]>tt || dis[x][y]>=dep[x][y]) continue;
            if (id==3 && s[x][y]==9) System.out.println(dis[x][y]);
            for (int i=0; i<4; i++) {
                int nx=x+directions[i][0], ny=y+directions[i][1];
                if (nx>0 && nx<=n && ny>0 && ny<=n && Character.isDigit(ma[nx][ny]) && dis[nx][ny]==Integer.MAX_VALUE) {
                    dis[nx][ny]=dis[x][y]+1;
                    q[++r]=nx*1000+ny;
                }
            }
        }
    }

    static boolean build() {
        Arrays.fill(d, 0);
        int l=1, r=1; q[l]=S; d[S]=1;
        while (l<=r) {
            int x=q[l++]; 
            for (int i=b[x]; i!=0; i=a[i][2]) {
                int y=a[i][0];
                if (d[y]!=0 || a[i][1]==0) continue;
                d[y]=d[x]+1; q[++r]=y;
                if (y==T) return true;
            }
        }
        return false;
    }

    static int dinic(int x, int flow) {
        if (x==T) return flow;
        int k=flow;
        for (int i=b[x]; i!=0; i=a[i][2]) {
            int y=a[i][0];
            if (d[y]!=d[x]+1 || a[i][1]==0) continue;
            int t=dinic(y, Math.min(k, a[i][1]));
            k-=t; a[i][1]-=t; a[i^1][1]+=t;
            if (k==0) return flow;
        }
        if (k==flow) d[x]=-1;
        return flow - k;
    }

    static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        tt = Integer.parseInt(st.nextToken());
        ma = new char[MAX_N+1][MAX_N+1];
        mb = new char[MAX_N+1][MAX_N+1];
        for (int i=1; i<=n; i++) {
            String line = br.readLine();
            for (int j=1; j<=n; j++) {
                ma[i][j] = line.charAt(j-1);
            }
        }
        for (int i=1; i<=n; i++) {
            String line = br.readLine();
            for (int j=1; j<=n; j++) {
                mb[i][j] = line.charAt(j-1);
            }
        }
        dep = new int[MAX_N+1][MAX_N+1];
        dis = new int[MAX_N+1][MAX_N+1];
        p = new int[MAX_N+1][MAX_N+1];
        s = new int[MAX_N+1][MAX_N+1];
        for (int[] row : dep) Arrays.fill(row, Integer.MAX_VALUE);
        for (int i=1; i<=n; i++) {
            for (int j=1; j<=n; j++) {
                if (ma[i][j]=='Z') {
                    bfs(i,j,false);
                }
            }
        }
        for (int i=1; i<=n; i++) {
            for (int j=1; j<=n; j++) {
                dep[i][j] = dis[i][j];
            }
        }
        int t=1;
        S=0; T=1;
        b = new int[MAX_T*2+10];
        a = new int[MAX_T*2+10][MAX_A];
        q = new int[MAX_Q+10];
        for (int[] row : a) Arrays.fill(row, 0);
        for (int[] row : dis) Arrays.fill(row, 0);
        for (int[] row : dep) Arrays.fill(row, 0);
        for (int[] row : p) Arrays.fill(row, 0);
        for (int[] row : s) Arrays.fill(row, 0);
        for (int i=1; i<=n; i++) {
            for (int j=1; j<=n; j++) {
                if (ma[i][j]>'0' && ma[i][j]<='9') {
                    p[i][j]=++t;
                    addEdge(S, t, ma[i][j]-'0');
                }
                if (mb[i][j]>'0' && mb[i][j]<='9') {
                    s[i][j]=++t;
                    addEdge(t, T, mb[i][j]-'0');
                }
            }
        }
        for (int i=1; i<=n; i++) {
            for (int j=1; j<=n; j++) {
                if (p[i][j]!=0) {
                    bfs(i,j,true);
                }
            }
        }
        int ans=0;
        while (build()) {
            ans+=dinic(S, Integer.MAX_VALUE);
        }
        System.out.println(ans);
    }
}
